import werkzeug._internal

def test_plain_int():
    # Test case where the input string is a valid integer in base 10
    assert werkzeug._internal._plain_int("123") == 123

    # Test case where the input string is a valid integer in base 16
    assert werkzeug._internal._plain_int("1A3F", base=16) == 6719

    # Test case where the input string has leading and trailing spaces
    assert werkzeug._internal._plain_int("   456   ") == 456

    # Test case where the input string is not a valid integer
    try:
        werkzeug._internal._plain_int("abc")
    except ValueError:
        pass
    else:
        assert False, "ValueError not raised for invalid integer"

    # Test case where the input string is not a valid integer in base 16
    try:
        werkzeug._internal._plain_int("GHI", base=16)
    except ValueError:
        pass
    else:
        assert False, "ValueError not raised for invalid integer in base 16"

test_plain_int()

