import werkzeug.middleware.proxy_fix
from werkzeug.wrappers import Request, Response

def test_proxyfix_no_http_host():
    def simple_app(environ, start_response):
        return Response('Hello, World!').(environ, start_response)

    app = werkzeug.middleware.proxy_fix.ProxyFix(simple_app, x_host=1)
    environ = {
        'HTTP_X_FORWARDED_HOST': 'example.com',
        'REQUEST_METHOD': 'GET',
        'PATH_INFO': '/'
    }

    @Request.application
    def test_app(request):
        assert request.host == 'example.com', "Expected host to be 'example.com'"
        return Response('Test passed')

    response = test_app(environ)
    assert response.data == b'Test passed', "Response data did not match expected output"

test_proxyfix_no_http_host()

