import rich._windows_renderer as mod_108
from rich._win32_console import LegacyWindowsTerm
from rich.segment import Segment, ControlCode, ControlType

class MockLegacyWindowsTerm(LegacyWindowsTerm):
    def __init__(self):
        self.written_text = []
        self.cursor_position = (0, 0)
        self.cursor_visible = True
        self.window_title = ""

    def write_text(self, text):
        self.written_text.append(text)

    def move_cursor_to(self, coordinates):
        self.cursor_position = (coordinates.row, coordinates.col)

    def hide_cursor(self):
        self.cursor_visible = False

    def show_cursor(self):
        self.cursor_visible = True

    def set_title(self, title):
        self.window_title = title

def test_unhandled_control_type():
    term = MockLegacyWindowsTerm()
    buffer = [
        Segment("Hello", style="bold", control=(ControlType.UNHANDLED,)),
    ]
    mod_108.legacy_windows_render(buffer, term)
    assert term.written_text == ["Hello"], "Text should be written"
    assert term.cursor_position == (0, 0), "Cursor position should remain unchanged"
    assert term.cursor_visible, "Cursor should remain visible"
    assert term.window_title == "", "Window title should remain unchanged"

test_unhandled_control_type()

